const body = $input.first().json;

if (!body.items || body.items.length === 0) {
  throw new Error('El pedido no tiene artículos');
}

const numeroPedido = 'PED-' + Date.now();
let total = 0;

const items = body.items.map(item => {
  const subtotal = (parseFloat(item.precio) || 0) * (parseInt(item.cantidad) || 1);
  total += subtotal;
  return {
    referencia: item.referencia || item.sku || 'SIN-REF',
    nombre: item.nombre || item.referencia || 'Artículo sin nombre',
    cantidad: parseInt(item.cantidad) || 1,
    precio_unit: parseFloat(item.precio) || 0,
    subtotal: subtotal
  };
});

return [{ json: {
  numero_pedido: numeroPedido,
  telefono: body.telefono || '',
  nombre_cliente: body.cliente || body.nombre_cliente || 'Cliente sin nombre',
  id_cliente: body.id_cliente || null,
  items_json: JSON.stringify(items),
  total: parseFloat(total.toFixed(2)),
  estado: 'pendiente',
  fecha_pedido: new Date().toISOString().slice(0, 19).replace('T', ' '),
  canal: body.canal || 'manual',
  canal_origen: body.canal_origen || 'directo',
  notas: body.notas || ''
}}];
